// Project wizard classes
class ConfirmModal extends Modal {

    constructor(
        app,
        title,
        message,
        confirmText = "Delete",
        confirmClass = "mod-warning"
    ) {
        super(app);

        this.title = title;
        this.message = message;
        this.confirmText = confirmText;
        this.confirmClass = confirmClass;

        this.resolvePromise = null;
        this.settled = false;
    }


    waitForConfirmation() {

        return new Promise(resolve => {

            this.resolvePromise = resolve;

            this.open();
        });
    }


    finish(result) {

        if (this.settled) return;

        this.settled = true;

        const resolve =
            this.resolvePromise;

        this.resolvePromise = null;

        this.close();

        resolve?.(result);
    }


    onOpen() {

        this.contentEl.addClass("hub-button-scope");

        this.contentEl.createEl("h2", {
            text: this.title
        });


        this.contentEl.createEl("p", {
            text: this.message
        });


        const actions =
            this.contentEl.createDiv({
                cls:
                    "hub-project-wizard-actions"
            });


        const cancel =
            actions.createEl("button", {
                text: "Cancel"
            });


        const confirm =
            actions.createEl("button", {
                text: this.confirmText
            });

        confirm.addClass(this.confirmClass);


        cancel.addEventListener(
            "click",
            () => this.finish(false)
        );


        confirm.addEventListener(
            "click",
            () => this.finish(true)
        );


        requestAnimationFrame(() => {
            confirm.focus();
        });
    }


    onClose() {

        this.contentEl.empty();


        /*
         * Closing with X or Escape
         * counts as cancellation.
         */

        if (!this.settled) {

            this.settled = true;

            const resolve =
                this.resolvePromise;

            this.resolvePromise = null;

            resolve?.(false);
        }
    }
}

class FocusListEditor {

    constructor(
        parent,
        projects,
        items
    ) {

        this.parent = parent;
        this.projects =
            (
                Array.isArray(projects)
                    ? projects
                    : []
            ).filter(
                project =>
                    project?.projectId &&
                    project?.name
            );
        this.rows = [];


        for (
            const item
            of normalizeFocusItems(items)
        ) {
            this.addRow(item);
        }


        this.ensureSuggestionRow();
    }


    addRow(
        value = null
    ) {

        if (this.rows.length >= 6) {
            return;
        }


        const row =
            this.parent.createDiv({
                cls:
                    "hub-project-advancement-focus-item"
            });


        const number =
            row.createSpan({
                cls:
                    "hub-project-advancement-focus-number"
            });


        const projectSelect =
            row.createEl(
                "select",
                {
                    cls:
                        "hub-project-advancement-focus-project"
                }
            );


        projectSelect.createEl(
            "option",
            {
                text:
                    "Project or Resource…",
                attr: {
                    value:
                        ""
                }
            }
        );


        for (
            const project
            of this.projects
        ) {
            projectSelect.createEl(
                "option",
                {
                    text:
                        project.name,
                    attr: {
                        value:
                            project.projectId
                    }
                }
            );
        }


        if (
            value?.projectId &&
            !this.projects.some(
                project =>
                    project.projectId ===
                        value.projectId
            )
        ) {
            projectSelect.createEl(
                "option",
                {
                    text:
                        value.projectName ??
                        "Unavailable Project or Resource",
                    attr: {
                        value:
                            value.projectId
                    }
                }
            );
        }


        projectSelect.value =
            value?.projectId ??
            (
                this.projects.length === 1
                    ? this.projects[0]
                        .projectId
                    : ""
            );


        const input =
            row.createEl(
                "input",
                {
                    type:
                        "text",
                    attr: {
                        maxlength:
                            "200",
                        placeholder:
                            "I will focus on…"
                    }
                }
            );


        input.value =
            value?.text ?? "";


        const remove =
            row.createEl(
                "button",
                {
                    cls:
                        "hub-project-advancement-remove-focus",
                    attr: {
                        type:
                            "button",
                        "aria-label":
                            "Remove focus"
                    }
                }
            );


        setIcon(remove, "x");


        const entry = {
            row,
            number,
            projectSelect,
            input
        };


        this.rows.push(entry);


        input.addEventListener(
            "input",
            () => {
                this.ensureSuggestionRow();
                this.syncRows();
            }
        );


        remove.addEventListener(
            "click",
            () => {

                row.remove();


                this.rows =
                    this.rows.filter(
                        item =>
                            item !== entry
                    );


                this.ensureSuggestionRow();
                this.syncRows();
            }
        );


        this.syncRows();
    }


    ensureSuggestionRow() {

        const hasEmptyRow =
            this.rows.some(
                entry =>
                    !entry.input.value.trim()
            );


        if (
            !hasEmptyRow &&
            this.rows.length < 6
        ) {
            this.addRow();
        }
    }


    syncRows() {

        this.rows.forEach(
            (entry, index) => {
                entry.number.setText(
                    `${index + 1}.`
                );
            }
        );
    }


    getValue() {

        const items = [];


        for (
            const entry
            of this.rows
        ) {

            const text =
                entry.input.value.trim();


            if (!text) {
                continue;
            }


            const projectId =
                entry.projectSelect.value;


            if (!projectId) {
                throw new Error(
                    "Choose a Project or Resource for each focus."
                );
            }


            const projectName =
                entry.projectSelect
                    .selectedOptions[0]
                    ?.textContent?.trim() ??
                "Unavailable project";


            items.push({
                text,
                projectId,
                projectName
            });
        }


        return items;
    }
}


class ProjectAdvancementModal
    extends Modal {

    constructor(
        app,
        {
            projects,
            resources = [],
            currentScores,
            currentSummaries = {},
            reportContexts = {},
            showNextFocus = false,
            currentFocus = [],
            focusProjects = [],
            onSave,
            onSaved,
            onCancel,
            title =
                "How much did you advance the project today?",
            requireEveryProject = true,
            allowNoProgress = false,
            saveLabel = "Save & close",
            showCancel = false
        }
    ) {

        super(app);


        this.projects =
            Array.isArray(projects)
                ? projects
                : [];


        this.resources =
            Array.isArray(resources)
                ? resources
                : [];


        this.progressItems = [
            ...this.projects,
            ...this.resources
        ];


        this.currentScores =
            currentScores ?? {};


        this.currentSummaries =
            currentSummaries ?? {};
        this.reportContexts = reportContexts;


        this.showNextFocus =
            showNextFocus;


        this.currentFocus =
            Array.isArray(currentFocus)
                ? currentFocus
                : [];


        this.focusProjects =
            Array.isArray(focusProjects)
                ? focusProjects
                : [];


        this.onSave =
            onSave;


        this.onSaved =
            onSaved;


        this.onCancel =
            onCancel;


        this.title =
            title;


        this.requireEveryProject =
            requireEveryProject;


        this.allowNoProgress =
            allowNoProgress;


        this.saveLabel =
            saveLabel;


        this.showCancel =
            showCancel;


        this.selectedScores =
            new Map();


        this.summaryInputs =
            new Map();


        this.settled =
            false;


        this.saving =
            false;


        for (
            const project
            of this.progressItems
        ) {

            const score =
                this.currentScores[
                    project.projectId
                ];


            if (
                Number.isInteger(score) &&
                score >= 1 &&
                score <= 4
            ) {

                this.selectedScores.set(
                    project.projectId,
                    score
                );
            }
        }
    }


    onOpen() {

        this.contentEl.addClass(
            "hub-project-advancement-modal", "hub-button-scope"
        );


        this.contentEl.createEl(
            "h2",
            {
                text:
                    this.title
            }
        );


        const guidance = this.contentEl.createDiv({ cls: 'hub-progress-rating-guidance' });
        guidance.createDiv({ text: "Rate the significance of today's work in each workspace." });
        guidance.createDiv({ cls: 'hub-progress-rating-hint', text: 'Hover over a rating for details.' });
        this.ratingTooltips?.dispose();
        this.ratingTooltips = createImmediateHubTooltip(this.contentEl);


        this.contentEl.createDiv({
            cls:
                "hub-project-advancement-divider"
        });


        // ---------- PROJECTS ----------

        const rows =
            this.contentEl.createDiv({
                cls:
                    "hub-project-advancement-projects"
            });


        for (
            let index = 0;
            index < this.progressItems.length;
            index++
        ) {

            if (
                index === this.projects.length &&
                this.projects.length > 0 &&
                this.resources.length > 0
            ) {
                rows.createDiv({
                    cls:
                        "hub-project-advancement-divider is-context-divider"
                });
            }


            const project =
                this.progressItems[index];
            const ratingOptions = progressRatingOptions(project);
            const bindRatingTooltip = (button, score) => {
                const option = ratingOptions.find(option => option.score === score);
                this.ratingTooltips.bind(button, {
                    title: `${option.score} · ${option.title}`, description: option.description
                });
            };

            const row =
                rows.createDiv({
                    cls:
                        "hub-project-advancement-row"
                });


            row.dataset.projectId =
                project.projectId;


            row.createDiv({
                cls:
                    "hub-project-advancement-name",

                text:
                    project.name
            });


            const context = this.reportContexts[project.projectId];
            if (context) {
                const evidence = renderReportEvidence(row, context);
                if (context.focus.length) focusSection(evidence, "Focus for this day", context.focus, "");
            }

            const choices =
                row.createDiv({
                    cls:
                        "hub-project-advancement-choices"
                });


            if (this.allowNoProgress) {

                const noProgressButton =
                    choices.createEl(
                        "button",
                        {
                            cls:
                                "hub-project-advancement-score",

                            text:
                                "0"
                        }
                    );


                noProgressButton.dataset.score =
                    "0";


                bindRatingTooltip(noProgressButton, 0);


                if (
                    this.selectedScores.get(
                        project.projectId
                    ) === 0
                ) {

                    noProgressButton.addClass(
                        "is-selected"
                    );
                }


                noProgressButton.setAttribute(
                    "aria-pressed",
                    String(
                        this.selectedScores.get(
                            project.projectId
                        ) === 0
                    )
                );


                noProgressButton.addEventListener(
                    "click",
                    () => {

                        this.selectScore(
                            row,
                            project.projectId,
                            0
                        );
                    }
                );
            }


            for (
                const option
                of PROJECT_ADVANCEMENT_OPTIONS
            ) {

                const button =
                    choices.createEl(
                        "button",
                        {
                            cls:
                                "hub-project-advancement-score",

                            text:
                                String(
                                    option.score
                                )
                        }
                    );


                button.dataset.score =
                    String(
                        option.score
                    );


                bindRatingTooltip(button, option.score);


                if (
                    this.selectedScores.get(
                        project.projectId
                    ) ===
                        option.score
                ) {

                    button.addClass(
                        "is-selected"
                    );
                }


                button.setAttribute(
                    "aria-pressed",
                    String(
                        this.selectedScores.get(
                            project.projectId
                        ) ===
                            option.score
                    )
                );


                button.addEventListener(
                    "click",
                    () => {

                        this.selectScore(
                            row,
                            project.projectId,
                            option.score
                        );
                    }
                );
            }


            const summaryField =
                row.createDiv({
                    cls:
                        "hub-project-advancement-summary"
                });


            const summaryInput =
                summaryField.createEl(
                    "textarea",
                    {
                        attr: {
                            rows: "3",
                            maxlength: "1000",
                            placeholder:
                                `Summarise progress on ${project.name}`
                        }
                    }
                );


            summaryInput.value =
                String(
                    this.currentSummaries[
                        project.projectId
                    ] ?? ""
                );


            this.summaryInputs.set(
                project.projectId,
                summaryInput
            );
        }


        if (this.showNextFocus) {

            this.contentEl.createDiv({
                cls:
                    "hub-project-advancement-divider"
            });


            const focusSection =
                this.contentEl.createDiv({
                    cls:
                        "hub-project-advancement-focus"
                });


            focusSection.createEl(
                "h3",
                {
                    text:
                        "What will you focus on next time?"
                }
            );


            this.focusList =
                focusSection.createDiv({
                    cls:
                        "hub-project-advancement-focus-list"
                });


            this.focusEditor =
                new FocusListEditor(
                    this.focusList,
                    this.focusProjects,
                    this.currentFocus
                );
        }


        // ---------- ACTIONS ----------

        const actions =
            this.contentEl.createDiv({
                cls:
                    "hub-project-advancement-actions"
            });


        if (this.showCancel) {

            const cancelButton =
                actions.createEl(
                    "button",
                    {
                        text:
                            "Cancel"
                    }
                );


            cancelButton.addEventListener(
                "click",
                () => {

                    this.close();
                }
            );
        }


        this.saveButton =
            actions.createEl(
                "button",
                {
                    text:
                        this.saveLabel
                }
            );


        this.saveButton.addClass(
            "mod-cta"
        );


        this.saveButton.addEventListener(
            "click",
            () => {

                this.save();
            }
        );


        this.updateSaveButton();
    }


    selectScore(
        row,
        projectId,
        score
    ) {
        if (score === 0) {
            const input = this.summaryInputs.get(projectId);
            if (input) input.value = "";
            this.currentSummaries[projectId] = "";
        }

        if (score === null) {

            this.selectedScores.delete(
                projectId
            );

        } else {

            this.selectedScores.set(
                projectId,
                score
            );
        }


        row.querySelectorAll(
            ".hub-project-advancement-score"
        )
            .forEach(
                button => {

                    button.toggleClass(
                        "is-selected",

                        (
                            button.dataset.score ===
                                ""
                                ? null
                                : Number(
                                    button.dataset.score
                                )
                        ) === score
                    );


                    button.setAttribute(
                        "aria-pressed",
                        String(
                            (
                                button.dataset.score ===
                                    ""
                                    ? null
                                    : Number(
                                        button.dataset.score
                                    )
                            ) === score
                        )
                    );
                }
            );


        this.updateSaveButton();
    }


    updateSaveButton() {

        if (!this.saveButton) {
            return;
        }


        this.saveButton.disabled =
            this.saving ||
            (
                this.requireEveryProject &&
                this.selectedScores.size !==
                    this.progressItems.length
            );
    }


    async save() {

        if (
            this.saving ||
            (
                this.requireEveryProject &&
                this.selectedScores.size !==
                    this.progressItems.length
            )
        ) {
            return;
        }


        this.saving =
            true;


        this.updateSaveButton();


        const scores =
            Object.fromEntries(
                [...this.selectedScores]
                    .filter(
                        ([, score]) =>
                            score !== 0
                    )
            );


        const summaries =
            Object.fromEntries(
                [...this.summaryInputs]
                    .map(
                        ([projectId, input]) => [
                            projectId,
                            input.value.trim()
                        ]
                    )
            );


        let focus;


        try {
            focus =
                this.focusEditor
                    ?.getValue() ?? [];

        } catch (error) {

            this.saving = false;
            this.updateSaveButton();


            new Notice(
                error.message
            );

            return;
        }


        try {

            await this.onSave({
                scores,
                summaries,
                focus
            });


            this.settled =
                true;


            this.close();


            this.onSaved?.();


        } catch (error) {

            console.error(
                "Could not save progress report:",
                error
            );


            this.saving =
                false;


            this.updateSaveButton();


            new Notice(
                "Could not save progress report."
            );
        }
    }


    onClose() {

        this.ratingTooltips?.dispose();
        this.contentEl.empty();


        if (
            !this.settled
        ) {

            this.onCancel?.();
        }
    }
}


class DailyFocusModal
    extends Modal {

    constructor(
        app,
        {
            date,
            items,
            nextItems = [],
            projects = [],
            onSave,
            onSaved,
            onCancel,
            title = null,
            saveLabel = "Save changes"
        }
    ) {

        super(app);


        this.date = date;
        this.items =
            Array.isArray(items)
                ? items
                : [];
        this.nextItems =
            Array.isArray(nextItems)
                ? nextItems
                : [];
        this.projects =
            Array.isArray(projects)
                ? projects
                : [];
        this.onSave = onSave;
        this.onSaved = onSaved;
        this.onCancel = onCancel;
        this.title = title;
        this.saveLabel = saveLabel;
        this.saving = false;
        this.settled = false;
    }


    onOpen() {

        this.contentEl.addClass(
            "hub-daily-focus-modal", "hub-button-scope"
        );


        this.contentEl.createEl(
            "h2",
            {
                text:
                    this.title ??
                    "Edit focus for today"
            }
        );


        this.list =
            this.contentEl.createDiv({
                cls:
                    "hub-project-advancement-focus-list"
            });


        this.focusEditor =
            new FocusListEditor(
                this.list,
                this.projects,
                this.items
            );


        this.contentEl.createDiv({
            cls:
                "hub-project-advancement-divider"
        });


        const nextSection =
            this.contentEl.createDiv({
                cls:
                    "hub-project-advancement-focus"
            });


        nextSection.createEl(
            "h2",
            {
                text:
                    "Edit focus for next day"
            }
        );


        const nextList =
            nextSection.createDiv({
                cls:
                    "hub-project-advancement-focus-list"
            });


        this.nextFocusEditor =
            new FocusListEditor(
                nextList,
                this.projects,
                this.nextItems
            );


        const actions =
            this.contentEl.createDiv({
                cls:
                    "hub-project-advancement-actions"
            });


        const cancel =
            actions.createEl(
                "button",
                {
                    text:
                        "Cancel"
                }
            );


        cancel.addEventListener(
            "click",
            () => this.close()
        );


        this.saveButton =
            actions.createEl(
                "button",
                {
                    text:
                        this.saveLabel
                }
            );


        this.saveButton.addClass(
            "mod-cta"
        );


        this.saveButton.addEventListener(
            "click",
            () => this.save()
        );
    }


    async save() {

        if (this.saving) {
            return;
        }


        this.saving = true;
        this.saveButton.disabled = true;


        try {

            const items =
                this.focusEditor
                    .getValue();

            const nextItems =
                this.nextFocusEditor
                    .getValue();

            await this.onSave({
                items,
                nextItems
            });
            this.settled = true;
            this.close();
            this.onSaved?.();

        } catch (error) {

            console.error(
                "Could not save daily focus:",
                error
            );


            this.saving = false;
            this.saveButton.disabled = false;


            new Notice(
                error.message ||
                "Could not save today's focus."
            );
        }
    }


    onClose() {
        this.contentEl.empty();


        if (!this.settled) {
            this.onCancel?.();
        }
    }
}

function confirmAction(
    app,
    title,
    message,
    confirmText = "Delete"
) {

    return new ConfirmModal(
        app,
        title,
        message,
        confirmText
    ).waitForConfirmation();
}

